INSERT INTO card (owner_type, owner_id, card_order_index, title, subtitle, end_text, why_this_question) VALUES ('simulator', (SELECT id FROM simulator WHERE title = 'Networking with Nerve: Assertive, Composed, Strategic, Kind'), 1, 'Phase 1: Preparation', 'Before the room', 'Ten minutes of clear preparation is worth more than two hours of anxious rehearsal, or three days of pretending you''ll figure it out in the moment.', 'This first scenario tests whether the learner defaults to avoidance (''just show up''), healthy strategic preparation, or over-preparation as a form of anxiety. It sets the tone for the rest of the simulator: networking is a skill that rewards small deliberate steps, not spontaneity or perfectionism.');

-- Component 1 for Card 0
INSERT INTO component_text (content) VALUES ('It is Tuesday morning. A colleague has just invited you to a networking mixer this Thursday evening, 40 people from your industry will be there, including two people you have been hoping to meet for months. You have three days to prepare (or not). What do you do?');
