-- Component 2 for Card 0
INSERT INTO component_mcq (question) VALUES ('It is Tuesday morning. A colleague has just invited you to a networking mixer this Thursday evening, 40 people from your industry will be there, including two people you have been hoping to meet for months. You have three days to prepare (or not). What do you do?');
INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'It is Tuesday morning. A colleague has just invited you to a networking mixer this Thursday evening, 40 people from your industry will be there, including two people you have been hoping to meet for months. You have three days to prepare (or not). What do you do?' ORDER BY id DESC LIMIT 1), 'You decide to just show up on Thursday and see what happens. Preparing feels like overthinking, and you trust yourself to be spontaneous in the moment.', 'Spontaneity has its place, but at events like this it usually means falling back on ''so, what do you do?'' and small talk. The women who leave events with the connections they wanted almost always spent 10 minutes preparing first. This is not overthinking. It is respect for your own time.');
