INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'It is Tuesday morning. A colleague has just invited you to a networking mixer this Thursday evening, 40 people from your industry will be there, including two people you have been hoping to meet for months. You have three days to prepare (or not). What do you do?' ORDER BY id DESC LIMIT 1), 'You spend 10 minutes on the three-question prep: one sentence on what you actually do, one thing you are genuinely curious about right now, and one thing you can offer to someone else.', 'Excellent. Those three questions do most of the work of the evening in advance. You will sound clearer, you will have real questions to ask, and you will stand out just by being one of the few people thinking ''what can I offer?'' instead of ''what can I get?''.');
