INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'It is Tuesday morning. A colleague has just invited you to a networking mixer this Thursday evening, 40 people from your industry will be there, including two people you have been hoping to meet for months. You have three days to prepare (or not). What do you do?' ORDER BY id DESC LIMIT 1), 'You spend two hours researching every attendee on LinkedIn and drafting a mental script for each of the two people you want to meet. You want to be fully ready.', 'Preparation is helpful, but two hours of scripted rehearsal often produces the opposite of what you want. You will sound rigid, you will listen less, and you will notice every deviation from your script as a small failure. Ten minutes of clear prep beats two hours of anxious rehearsal.');
