INSERT INTO card (owner_type, owner_id, card_order_index, title, subtitle, end_text, why_this_question) VALUES ('simulator', (SELECT id FROM simulator WHERE title = 'Networking with Nerve: Assertive, Composed, Strategic, Kind'), 2, 'Phase 2: The Opener', 'Starting the conversation', 'You do not need a perfect script. You need to open with something specific about them, and one real question. That is the whole trick.', 'This scenario tests the moment women most often lose networking opportunities, the small window right before an opener. The three actions represent the three dominant patterns: freeze/avoid, warm strategic opener, or self-focused pitch. It teaches that assertiveness and warmth are not opposites, they combine in the same 15 seconds.');

-- Component 1 for Card 1
INSERT INTO component_text (content) VALUES ('You arrive at the event. Across the room, you see one of the two people you were hoping to meet, a senior director in your field, standing alone for a moment with a glass of water. This is your window. What do you do?');
INSERT INTO card_contains (card_id, component_type, component_order_index, component_id) VALUES ((SELECT id FROM card WHERE title = 'Phase 2: The Opener' AND owner_id = (SELECT id FROM simulator WHERE title = 'Networking with Nerve: Assertive, Composed, Strategic, Kind') LIMIT 1), 'text', 1, LAST_INSERT_ID());

-- Component 2 for Card 1
INSERT INTO component_mcq (question) VALUES ('You arrive at the event. Across the room, you see one of the two people you were hoping to meet, a senior director in your field, standing alone for a moment with a glass of water. This is your window. What do you do?');
INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'You arrive at the event. Across the room, you see one of the two people you were hoping to meet, a senior director in your field, standing alone for a moment with a glass of water. This is your window. What do you do?' ORDER BY id DESC LIMIT 1), 'You freeze, tell yourself she looks busy, and go get a drink to buy yourself time. Maybe another moment will come naturally later.', 'That ''natural moment'' rarely arrives, the room fills up, other people approach her, the window closes. Freezing is human, but it is also the number one reason women leave events regretting the conversations they did not have. Nothing dramatic needed to be said. A simple ''hi, I''m [name], I really enjoyed your talk last month on X'' would have been enough.');
