     AND option_text = 'You freeze, tell yourself she looks busy, and go get a drink to buy yourself time. Maybe another moment will come naturally later.' 
     ORDER BY id DESC LIMIT 1), (SELECT id FROM simulator_metric WHERE name = 'Assertiveness' LIMIT 1), -15);
