INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'You arrive at the event. Across the room, you see one of the two people you were hoping to meet, a senior director in your field, standing alone for a moment with a glass of water. This is your window. What do you do?' ORDER BY id DESC LIMIT 1), 'You walk over, extend a hand, and open with: ''Hi, I''m [name]. I know you don''t know me, I''ve been hoping to catch you because I really valued your recent post on X. What are you working on that you''re excited about right now?''', 'This is textbook. You named yourself, you named a specific reason (not generic flattery), and you closed with a real question about her, not about you. Almost no one at this event will open a conversation this well. You just made yourself memorable in 15 seconds.');
