INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'You arrive at the event. Across the room, you see one of the two people you were hoping to meet, a senior director in your field, standing alone for a moment with a glass of water. This is your window. What do you do?' ORDER BY id DESC LIMIT 1), 'You approach her and immediately launch into your elevator pitch: your background, your current role, the project you''re working on, and why you''d love to work with her someday.', 'You showed courage in approaching, which matters. But leading with your pitch tells her the conversation is about you, not her. Senior people meet a lot of pitchers. The women who make a real impression open with genuine curiosity about the other person''s work first.');
