-- ============================================
INSERT INTO card (owner_type, owner_id, card_order_index, title, subtitle, end_text, why_this_question) VALUES ('simulator', (SELECT id FROM simulator WHERE title = 'Networking with Nerve: Assertive, Composed, Strategic, Kind'), 3, 'Phase 3: The Dismissal', 'Not taking it personally', 'Someone''s rudeness is data about them, not about you. Composure is the skill of remembering that in real time.', 'Networking regularly involves people who are distracted, tired, or genuinely rude. This scenario teaches that the difference between women who build strong networks and those who don''t is not who gets treated well, it is how they respond when they''re treated badly. Composure, not confrontation, is the strategic move.');

-- Component 1 for Card 2
INSERT INTO component_text (content) VALUES ('You are three sentences into introducing your work when the person you are speaking with looks over your shoulder, half-waves at someone more senior, and says distractedly: ''sorry, what did you say your name was again?'', and then immediately: ''is Sarah here yet?''. What do you do?');
INSERT INTO card_contains (card_id, component_type, component_order_index, component_id) VALUES ((SELECT id FROM card WHERE title = 'Phase 3: The Dismissal' AND owner_id = (SELECT id FROM simulator WHERE title = 'Networking with Nerve: Assertive, Composed, Strategic, Kind') LIMIT 1), 'text', 1, LAST_INSERT_ID());

-- Component 2 for Card 2
INSERT INTO component_mcq (question) VALUES ('You are three sentences into introducing your work when the person you are speaking with looks over your shoulder, half-waves at someone more senior, and says distractedly: ''sorry, what did you say your name was again?'', and then immediately: ''is Sarah here yet?''. What do you do?');
INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'You are three sentences into introducing your work when the person you are speaking with looks over your shoulder, half-waves at someone more senior, and says distractedly: ''sorry, what did you say your name was again?'', and then immediately: ''is Sarah here yet?''. What do you do?' ORDER BY id DESC LIMIT 1), 'You feel a flash of embarrassment, mumble your name again, and quickly find an excuse to step away. This person clearly is not interested in you.', 'Understandable, but you just paid the cost of someone else''s bad manners. Their distraction is not a comment on you, it is a comment on them, on the event, or on their own bad day. Leaving quickly turns their small rudeness into your loss. Not taking things personally is a muscle. This was a chance to train it.');
