     ORDER BY id DESC LIMIT 1), (SELECT id FROM simulator_metric WHERE name = 'Composure' LIMIT 1), -15);
INSERT INTO multiple_choices_options_weights (multiple_choices_options_id, simulator_metric_id, weight) VALUES ((SELECT id FROM multiple_choices_options 
     WHERE mcq_id = (SELECT id FROM component_mcq WHERE question = 'You are three sentences into introducing your work when the person you are speaking with looks over your shoulder, half-waves at someone more senior, and says distractedly: ''sorry, what did you say your name was again?'', and then immediately: ''is Sarah here yet?''. What do you do?') 
     AND option_text = 'You feel a flash of embarrassment, mumble your name again, and quickly find an excuse to step away. This person clearly is not interested in you.' 
     ORDER BY id DESC LIMIT 1), (SELECT id FROM simulator_metric WHERE name = 'Strategic warmth' LIMIT 1), 0);
INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'You are three sentences into introducing your work when the person you are speaking with looks over your shoulder, half-waves at someone more senior, and says distractedly: ''sorry, what did you say your name was again?'', and then immediately: ''is Sarah here yet?''. What do you do?' ORDER BY id DESC LIMIT 1), 'You smile, repeat your name once clearly, and say warmly: ''I''ll let you catch Sarah, it was nice to meet you briefly. If you''re open to it, I''d love to send you a short message after the event.''', 'This is very good. You did not perform hurt feelings, you did not chase her attention, and you did not disappear either. You reclaimed the exit on your own terms, kept the door open, and moved on. Almost no one handles this moment this cleanly. It signals real maturity.');
INSERT INTO multiple_choices_options_weights (multiple_choices_options_id, simulator_metric_id, weight) VALUES ((SELECT id FROM multiple_choices_options 
