INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'You are three sentences into introducing your work when the person you are speaking with looks over your shoulder, half-waves at someone more senior, and says distractedly: ''sorry, what did you say your name was again?'', and then immediately: ''is Sarah here yet?''. What do you do?' ORDER BY id DESC LIMIT 1), 'You raise your voice slightly and say: ''Excuse me, I was talking. Could you at least listen before you look for someone more important?''', 'The feeling behind this is valid, but the delivery costs more than it gains. You will be remembered as ''difficult'' rather than as someone worth taking seriously. Assertiveness is not the same as counter-rudeness. The stronger move is composure plus a clean exit, as in option 2.');
