INSERT INTO card (owner_type, owner_id, card_order_index, title, subtitle, end_text, why_this_question) VALUES ('simulator', (SELECT id FROM simulator WHERE title = 'Networking with Nerve: Assertive, Composed, Strategic, Kind'), 4, 'Phase 4: The Kind Exit', 'Leaving without being rude', 'A clean, warm exit is more respectful than an unclear stay. You are not rude for leaving, you are responsible for your own time.', 'Women are socialised to stay in conversations they want to leave, and to interpret leaving as rudeness. This scenario teaches the specific technique of the ''warm exit'', a short, honest sentence that ends the conversation without ending the relationship. It is one of the single most useful phrases in professional networking.');

-- Component 1 for Card 3
INSERT INTO component_text (content) VALUES ('You have been in one conversation for 25 minutes. The person is friendly, but they are monopolising your time telling you about their project. Two of the people you wanted to meet just walked in. You need to leave this conversation without being rude. What do you do?');
INSERT INTO card_contains (card_id, component_type, component_order_index, component_id) VALUES ((SELECT id FROM card WHERE title = 'Phase 4: The Kind Exit' AND owner_id = (SELECT id FROM simulator WHERE title = 'Networking with Nerve: Assertive, Composed, Strategic, Kind') LIMIT 1), 'text', 1, LAST_INSERT_ID());

-- Component 2 for Card 3
INSERT INTO component_mcq (question) VALUES ('You have been in one conversation for 25 minutes. The person is friendly, but they are monopolising your time telling you about their project. Two of the people you wanted to meet just walked in. You need to leave this conversation without being rude. What do you do?');
INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'You have been in one conversation for 25 minutes. The person is friendly, but they are monopolising your time telling you about their project. Two of the people you wanted to meet just walked in. You need to leave this conversation without being rude. What do you do?' ORDER BY id DESC LIMIT 1), 'You keep nodding politely, glance at your phone twice to signal you need to leave, and hope she takes the hint. After all, you don''t want to be rude.', 'Hint-dropping is a common trap, you feel polite but you are actually being unclear, which is a form of unkindness. You will end up feeling drained, resentful, and you will miss the people you actually wanted to meet. Kindness is not the same as agreeing to be captured. A clear warm exit is more respectful than a fake nod.');
