INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'You have been in one conversation for 25 minutes. The person is friendly, but they are monopolising your time telling you about their project. Two of the people you wanted to meet just walked in. You need to leave this conversation without being rude. What do you do?' ORDER BY id DESC LIMIT 1), 'You wait for a natural pause, smile, and say: ''This has been really interesting, I''d love to hear more later. I''m going to say hi to a few people before the room fills up. Can I find you on LinkedIn so we can stay in touch?''', 'Excellent. You did three things well: you acknowledged the conversation warmly, you left cleanly on your own terms, and you kept the relationship open. Almost no one at this event will exit a conversation this well. This is exactly what assertive kindness looks like.');
