INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'You have been in one conversation for 25 minutes. The person is friendly, but they are monopolising your time telling you about their project. Two of the people you wanted to meet just walked in. You need to leave this conversation without being rude. What do you do?' ORDER BY id DESC LIMIT 1), 'You invent a fake phone call: ''sorry, I have to take this,'' and walk away. It gets you out, and she won''t feel personally rejected.', 'The fake call works once. But it teaches you that you can only leave conversations by lying, which is a very expensive habit to build. It also usually shows, people can tell. The real skill is exiting cleanly and warmly, without a script that makes you feel small.');
