INSERT INTO card (owner_type, owner_id, card_order_index, title, subtitle, end_text, why_this_question) VALUES ('simulator', (SELECT id FROM simulator WHERE title = 'Networking with Nerve: Assertive, Composed, Strategic, Kind'), 5, 'Phase 5: The Message', 'Reaching out online', 'A specific, four-sentence message gets more replies than a long, generic one, every time. Warmth is measured in specifics, not in words.', 'Online outreach is where most networking attempts quietly fail, either because the message is too vague to reply to, or too long to read. This scenario teaches the four-sentence structure that combines assertiveness (a clear ask) with warmth (specific, honest, respectful of her time).');

-- Component 1 for Card 4
INSERT INTO component_text (content) VALUES ('Two days after the event, you want to write to the senior director from Card 2. You had a great 10-minute conversation with her about a project she''s leading. You would love a 20-minute call to ask her advice about a similar challenge you''re facing. How do you write the message?');
INSERT INTO card_contains (card_id, component_type, component_order_index, component_id) VALUES ((SELECT id FROM card WHERE title = 'Phase 5: The Message' AND owner_id = (SELECT id FROM simulator WHERE title = 'Networking with Nerve: Assertive, Composed, Strategic, Kind') LIMIT 1), 'text', 1, LAST_INSERT_ID());

-- Component 2 for Card 4
INSERT INTO component_mcq (question) VALUES ('Two days after the event, you want to write to the senior director from Card 2. You had a great 10-minute conversation with her about a project she''s leading. You would love a 20-minute call to ask her advice about a similar challenge you''re facing. How do you write the message?');
INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'Two days after the event, you want to write to the senior director from Card 2. You had a great 10-minute conversation with her about a project she''s leading. You would love a 20-minute call to ask her advice about a similar challenge you''re facing. How do you write the message?' ORDER BY id DESC LIMIT 1), 'You write a warm 4-sentence message: one specific line about your conversation, one honest sentence about why you''re writing, one clear small ask (a 20-minute call), and a graceful exit (''totally fine if it''s not a good moment'').', 'This is exactly the structure that gets replies. Specific, honest, small, respectful. You will be in the small minority of people whose messages actually land, and even if she says no, she will remember you well. This is strategic warmth in action.');
