     AND option_text = 'You write a warm 4-sentence message: one specific line about your conversation, one honest sentence about why you''re writing, one clear small ask (a 20-minute call), and a graceful exit (''totally fine if it''s not a good moment'').' 
     ORDER BY id DESC LIMIT 1), (SELECT id FROM simulator_metric WHERE name = 'Assertiveness' LIMIT 1), 20);
