INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'Two days after the event, you want to write to the senior director from Card 2. You had a great 10-minute conversation with her about a project she''s leading. You would love a 20-minute call to ask her advice about a similar challenge you''re facing. How do you write the message?' ORDER BY id DESC LIMIT 1), 'You send: ''Hi! Great to meet you last week. Would love to pick your brain sometime. Let me know when works for you!''', 'This lands softly. ''Pick your brain'' is a phrase busy senior people quietly dread, it signals you haven''t thought about what you actually need. ''Sometime'' is not a real ask. And ''let me know when works for you'' hands her the entire logistical burden. She likes you, but she probably will not reply. Specificity is warmth.');
