     AND option_text = 'You send: ''Hi! Great to meet you last week. Would love to pick your brain sometime. Let me know when works for you!''' 
     ORDER BY id DESC LIMIT 1), (SELECT id FROM simulator_metric WHERE name = 'Assertiveness' LIMIT 1), -5);
