     AND option_text = 'You send: ''Hi! Great to meet you last week. Would love to pick your brain sometime. Let me know when works for you!''' 
     ORDER BY id DESC LIMIT 1), (SELECT id FROM simulator_metric WHERE name = 'Composure' LIMIT 1), 0);
INSERT INTO multiple_choices_options_weights (multiple_choices_options_id, simulator_metric_id, weight) VALUES ((SELECT id FROM multiple_choices_options 
     WHERE mcq_id = (SELECT id FROM component_mcq WHERE question = 'Two days after the event, you want to write to the senior director from Card 2. You had a great 10-minute conversation with her about a project she''s leading. You would love a 20-minute call to ask her advice about a similar challenge you''re facing. How do you write the message?') 
     AND option_text = 'You send: ''Hi! Great to meet you last week. Would love to pick your brain sometime. Let me know when works for you!''' 
