INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'Two days after the event, you want to write to the senior director from Card 2. You had a great 10-minute conversation with her about a project she''s leading. You would love a 20-minute call to ask her advice about a similar challenge you''re facing. How do you write the message?' ORDER BY id DESC LIMIT 1), 'You write a 3-paragraph message explaining your background, your career goals, your current challenge in detail, and asking for her advice on all of it, plus an introduction to two people she knows.', 'The care behind this is visible, but the length works against you. Senior women receive many long messages every week and rarely have time to read them, let alone respond. The short, specific message with one small ask outperforms the long detailed one every time. Less is not just faster, it is more respectful.');
