INSERT INTO card (owner_type, owner_id, card_order_index, title, subtitle, end_text, why_this_question) VALUES ('simulator', (SELECT id FROM simulator WHERE title = 'Networking with Nerve: Assertive, Composed, Strategic, Kind'), 6, 'Phase 6: The Follow-Up', 'Bridging the gap', 'The follow-up is the relationship. The first conversation is just the beginning. Cleverness is not required. Being on time is.', 'This final scenario tests the moment where most networking attempts quietly die: the unfollowed-up conversation. It teaches that follow-ups are judged on timeliness and specificity, not on cleverness or eloquence, and that over-apologising is its own form of self-diminishment.');

-- Component 1 for Card 5
INSERT INTO component_text (content) VALUES ('It has now been 5 days since a great coffee with someone you really connected with. You keep meaning to send a follow-up message, and you keep not doing it. The longer you wait, the more awkward it feels. What do you do?');
