-- Component 2 for Card 5
INSERT INTO component_mcq (question) VALUES ('It has now been 5 days since a great coffee with someone you really connected with. You keep meaning to send a follow-up message, and you keep not doing it. The longer you wait, the more awkward it feels. What do you do?');
INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'It has now been 5 days since a great coffee with someone you really connected with. You keep meaning to send a follow-up message, and you keep not doing it. The longer you wait, the more awkward it feels. What do you do?' ORDER BY id DESC LIMIT 1), 'You keep waiting until you have ''something clever'' to say. You''ll send it when the right words come. Better late and perfect than early and average.', 'This is one of the most common self-sabotages in networking. ''Waiting for the right words'' is almost always waiting for the anxiety to disappear, and it will not disappear. Meanwhile, the memory of your conversation fades on her side. Follow-ups are not judged on cleverness. They are judged on warmth and timeliness. Cleverness is a trap.');
