INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'It has now been 5 days since a great coffee with someone you really connected with. You keep meaning to send a follow-up message, and you keep not doing it. The longer you wait, the more awkward it feels. What do you do?' ORDER BY id DESC LIMIT 1), 'You send a 3-sentence message today: ''Really enjoyed our conversation last week, I thought more about what you said about X and it made me realise Y. No need to reply, just wanted to say thank you.''', 'This is textbook. Warm, specific, short, no obligation. You just placed yourself in the small minority of people who actually follow up, which, statistically, is the single biggest differentiator between women who build strong networks and those who don''t. Well done.');
