INSERT INTO multiple_choices_options (mcq_id, option_text, feedback) VALUES ((SELECT id FROM component_mcq WHERE question = 'It has now been 5 days since a great coffee with someone you really connected with. You keep meaning to send a follow-up message, and you keep not doing it. The longer you wait, the more awkward it feels. What do you do?' ORDER BY id DESC LIMIT 1), 'You send a long apology message: ''I''m so sorry I didn''t get back to you sooner, this week has been so crazy, I hope you don''t think I''m rude, I really did enjoy our conversation and I meant to write earlier but…'' and go on to explain the delay in detail.', 'The instinct to apologise is understandable, but a long apology draws more attention to a gap she probably didn''t notice. It also puts you in a lower-status position from the start of the message, and forces her to reassure you. A clean three-sentence message with no apology outperforms a long apologetic one, almost every time.');
