-- Feedback for metric 'Assertiveness' (Score 0-49)
INSERT INTO simulator_feedback_tiers (simulator_id, metric_id, min_score, max_score, strength_result, risk_result, micro_practice, recommended_module_id, recommendation_reason) VALUES ((SELECT id FROM simulator WHERE title = 'Networking with Nerve: Assertive, Composed, Strategic, Kind'), (SELECT id FROM simulator_metric WHERE name = 'Assertiveness' LIMIT 1), 0, 49, 'You are considerate and careful with people, you rarely make anyone feel small.', 'You hesitate to open conversations, exit them, or ask for what you want. Politeness can quietly cost you the connections you were hoping to build.', 'Before your next event, write down one short opener you can actually say out loud. Practise it once in the mirror. That is enough.', NULL, 'When assertiveness is low, the most valuable step is reducing the friction of the first sentence. The Networking course walks you through the three-question prep, honest openers, and the warm exit, the exact scripts that make it easier to speak up without feeling aggressive or rehearsed.');

-- Feedback for metric 'Assertiveness' (Score 50-85)
INSERT INTO simulator_feedback_tiers (simulator_id, metric_id, min_score, max_score, strength_result, risk_result, micro_practice, recommended_module_id, recommendation_reason) VALUES ((SELECT id FROM simulator WHERE title = 'Networking with Nerve: Assertive, Composed, Strategic, Kind'), (SELECT id FROM simulator_metric WHERE name = 'Assertiveness' LIMIT 1), 50, 85, 'You can ask for what you need and hold your ground when the situation calls for it.', 'You still hesitate in higher-stakes moments, with senior people, in group settings, or when you feel dismissed.', 'Pick one situation this week where you would normally stay quiet and say the honest, warm version instead. One sentence is enough.', NULL, 'You have a working level of assertiveness, the next step is making it reliable under pressure. The Networking course gives you the scripts and mindset for the harder moments: dismissive audiences, monopolising conversations, and the follow-up messages you have been postponing.');

-- Feedback for metric 'Assertiveness' (Score 85-100)
INSERT INTO simulator_feedback_tiers (simulator_id, metric_id, min_score, max_score, strength_result, risk_result, micro_practice, recommended_module_id, recommendation_reason) VALUES ((SELECT id FROM simulator WHERE title = 'Networking with Nerve: Assertive, Composed, Strategic, Kind'), (SELECT id FROM simulator_metric WHERE name = 'Assertiveness' LIMIT 1), 85, 100, 'You ask clearly, exit cleanly, and hold your ground with warmth. Your presence is felt.', 'None. Watch that assertiveness stays paired with genuine curiosity about others, the combination is what makes it landing rather than intimidating.', 'Mentor a woman in your circle who struggles to speak up. Teach her one script that changed things for you.', NULL, 'Confident assertiveness becomes most powerful when it is paired with genuine curiosity and generosity. The Networking course helps you keep your directness in service of relationship quality, so your clarity opens doors instead of closing them, and you actively lift the less-confident women in the room around you.');

-- Feedback for metric 'Composure' (Score 0-49)
INSERT INTO simulator_feedback_tiers (simulator_id, metric_id, min_score, max_score, strength_result, risk_result, micro_practice, recommended_module_id, recommendation_reason) VALUES ((SELECT id FROM simulator WHERE title = 'Networking with Nerve: Assertive, Composed, Strategic, Kind'), (SELECT id FROM simulator_metric WHERE name = 'Composure' LIMIT 1), 0, 49, 'You are emotionally attuned, you notice when someone is distracted, tired, or off. That sensitivity is a real strength.', 'You often take other people''s bad moments personally. A distracted look or a short reply can linger for hours or days and quietly discourage you from reaching out again.', 'The next time someone is distracted in a conversation with you, silently repeat: ''that is information about their day, not about me.'' Then continue as normal.', NULL, 'When composure is low, small social frictions carry outsized weight, and that weight is one of the main reasons women pull back from networking. The Networking course teaches you how to read a dismissive moment as data about the other person, not as evidence about your own worth, so you keep showing up.');

-- Feedback for metric 'Composure' (Score 50-85)
INSERT INTO simulator_feedback_tiers (simulator_id, metric_id, min_score, max_score, strength_result, risk_result, micro_practice, recommended_module_id, recommendation_reason) VALUES ((SELECT id FROM simulator WHERE title = 'Networking with Nerve: Assertive, Composed, Strategic, Kind'), (SELECT id FROM simulator_metric WHERE name = 'Composure' LIMIT 1), 50, 85, 'You recover well from small social frictions and stay open to reconnecting.', 'You still take some interactions personally, usually with senior people, or in moments where you felt you did not perform at your best.', 'After a conversation that felt off, ask yourself: ''what is one non-personal reason this might have gone the way it did?'', before your inner critic gets there first.', NULL, 'You already have a working composure, the next step is protecting it in higher-stakes moments. The Networking course helps you build a repeatable inner script for handling dismissive or distracted people, so you leave events remembering the connections you made, not the small stumbles.');

-- Feedback for metric 'Composure' (Score 85-100)
INSERT INTO simulator_feedback_tiers (simulator_id, metric_id, min_score, max_score, strength_result, risk_result, micro_practice, recommended_module_id, recommendation_reason) VALUES ((SELECT id FROM simulator WHERE title = 'Networking with Nerve: Assertive, Composed, Strategic, Kind'), (SELECT id FROM simulator_metric WHERE name = 'Composure' LIMIT 1), 85, 100, 'You handle rudeness, distraction, and awkward moments without letting them define you.', 'None. Just watch that composure does not tip into detachment, you still want to be reachable, not armoured.', 'Notice one moment this week where composure served you. Name it clearly to yourself, that is the reference point you want to build on.', NULL, 'Strong composure is one of the most valuable networking assets, because it lets you keep showing up when others quietly retreat. The Networking course helps you channel that composure into strategic follow-up habits, so the calm you already have translates into connections that actually mature over time.');

-- Feedback for metric 'Strategic warmth' (Score 0-49)
INSERT INTO simulator_feedback_tiers (simulator_id, metric_id, min_score, max_score, strength_result, risk_result, micro_practice, recommended_module_id, recommendation_reason) VALUES ((SELECT id FROM simulator WHERE title = 'Networking with Nerve: Assertive, Composed, Strategic, Kind'), (SELECT id FROM simulator_metric WHERE name = 'Strategic warmth' LIMIT 1), 0, 49, 'You are honest and unpretentious. People sense they are dealing with a real person, not a performance.', 'You either go too transactional (''what can I get from this person?'') or too diffuse (''everyone is lovely, but nothing follows''). You leave events without a clear next step.', 'Before your next networking moment, write down one specific thing you can offer to someone, an intro, a resource, a compliment on real work. One is enough.', NULL, 'When strategic warmth is low, networking often collapses into either awkward transaction or pleasant vagueness. The Networking course teaches you how to combine specificity with generosity, the openers, four-sentence messages, and 48-hour follow-ups that turn casual conversations into real relationships.');

-- Feedback for metric 'Strategic warmth' (Score 50-85)
INSERT INTO simulator_feedback_tiers (simulator_id, metric_id, min_score, max_score, strength_result, risk_result, micro_practice, recommended_module_id, recommendation_reason) VALUES ((SELECT id FROM simulator WHERE title = 'Networking with Nerve: Assertive, Composed, Strategic, Kind'), (SELECT id FROM simulator_metric WHERE name = 'Strategic warmth' LIMIT 1), 50, 85, 'You know how to be warm and specific at the same time. People remember conversations with you.', 'You sometimes hesitate to make a clear ask, or you follow up warmly without proposing a next step. Warmth needs a container to move relationships forward.', 'In your next follow-up message, add one specific, small ask or offer, a 20-minute call, an introduction, a resource you could share. Warmth plus a container.', NULL, 'You have the harder half of strategic warmth already, genuine care and specific attention. The Networking course helps you add the missing piece: the small, honest, clear ask or offer that turns warm moments into concrete relationships. This is where good networkers become excellent ones.');

-- Feedback for metric 'Strategic warmth' (Score 85-100)
INSERT INTO simulator_feedback_tiers (simulator_id, metric_id, min_score, max_score, strength_result, risk_result, micro_practice, recommended_module_id, recommendation_reason) VALUES ((SELECT id FROM simulator WHERE title = 'Networking with Nerve: Assertive, Composed, Strategic, Kind'), (SELECT id FROM simulator_metric WHERE name = 'Strategic warmth' LIMIT 1), 85, 100, 'You combine genuine warmth with strategic clarity. People feel seen by you and also know exactly what you''re asking for.', 'None. Just make sure you are letting the warmth flow both ways, accept help and connection as freely as you offer them.', 'Reach out to one person in your network this week with no ask at all, only a thank-you or a piece of information they would find useful. Warmth without transaction.', NULL, 'Strategic warmth at this level is a rare and valuable capacity, it is what lets you build a network of people who both trust you and know how to help you. The Networking course helps you deepen that further, especially in the long-term maintenance of relationships: how to stay meaningfully present in people''s lives without turning every touch into a transaction.');

